import{_ as e,o as r,c as t,a6 as i}from"./chunks/framework.QQy01QNh.js";const u=JSON.parse('{"title":"怎样使用这座阅读站","description":"沿原文顺序阅读，在对应章节之后查看解释、图示与案例，也可以把明确的问题交给Xikari Skill继续研究。","frontmatter":{"title":"怎样使用这座阅读站","description":"沿原文顺序阅读，在对应章节之后查看解释、图示与案例，也可以把明确的问题交给Xikari Skill继续研究。"},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),o={name:"guide/index.md"};function h(l,a,n,d,s,p){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="怎样使用这座阅读站" tabindex="-1">怎样使用这座阅读站 <a class="header-anchor" href="#怎样使用这座阅读站" aria-label="Permalink to &quot;怎样使用这座阅读站&quot;">​</a></h1><p>这里以完整原文为阅读主线。先读一节原文，再接着看该节的讲解、图示与案例；需要核对相邻定义和论证时，沿目录回到对应位置。</p><h2 id="第一次来-先把一节原文读完整" tabindex="-1">第一次来，先把一节原文读完整 <a class="header-anchor" href="#第一次来-先把一节原文读完整" aria-label="Permalink to &quot;第一次来，先把一节原文读完整&quot;">​</a></h2><p>从<a href="./../">全书目录</a>进入，按原书顺序阅读。原文的定义、公式、条件与限制都保留在原位；带讲解的章节在原文之后以“读懂这一节”接续展开，可以对照着读，也可以用“只看原文”暂时隐藏讲解。</p><p>可以先看<a href="./../theory/part-03.html#section-3-3">§3.3 有效反馈</a>、<a href="./../theory/part-04.html#section-4-6">§4.6 表示与干预</a>或<a href="./../theory/appendix-c.html#section-c-7">附录 C.7 表示充分与规则执行</a>的原文与讲解如何衔接。遇到真实案例时，先确认来源讲了什么，再看它帮助区分了哪项关系；不要因为术语相似，就认定不同案例具有相同机制。</p><h2 id="已经有问题-直接查概念" tabindex="-1">已经有问题，直接查概念 <a class="header-anchor" href="#已经有问题-直接查概念" aria-label="Permalink to &quot;已经有问题，直接查概念&quot;">​</a></h2><p>顶部搜索可以查概念、案例与原文。可以输入一个词，也可以用空格连接多个关键词，例如“反馈 机制”。搜索结果会显示出处与上下文；进入结果后再读完整段落。</p><p>原文按部分和附录组织。左侧目录切换章节，右侧目录定位当前页；手机上使用上方的“阅读目录”和页内目录。字号按钮适合较长时间阅读，浅色与深色主题只改变显示。</p><h2 id="想完整读书-沿原文顺序走" tabindex="-1">想完整读书，沿原文顺序走 <a class="header-anchor" href="#想完整读书-沿原文顺序走" aria-label="Permalink to &quot;想完整读书，沿原文顺序走&quot;">​</a></h2><p>从<a href="./../theory/">范围与阅读方式</a>进入。十六部分保留原顺序；附录 A 按完整接口卡、附录 D 按领域分开。上一篇与下一篇连接阅读路径。</p><p>需要保存时可<a href="./../downloads.html">下载完整原文与 Word 阅读版</a>。网站中的例解另有出处，引用理论定义请使用原文的节号。</p><h2 id="把理解带到自己的问题中" tabindex="-1">把理解带到自己的问题中 <a class="header-anchor" href="#把理解带到自己的问题中" aria-label="Permalink to &quot;把理解带到自己的问题中&quot;">​</a></h2><p>使用已经安装的 Xikari Skill 时，明确告诉它你真正要解决的问题、已有材料、希望得到的成果与现实限制。例如：</p><blockquote><p>使用 xi-kari-skill 分析：我们不断收到用户反馈，但同类问题仍然重复发生。这里是反馈记录、处理流程和最近几次修改。请辨明问题可能停在哪一环，并给出有理由的判断和具体改进方案。</p></blockquote><p>这个示例规定的是任务，不预设故障原因。实际分析仍要学习完整理论、读取材料、比较解释并处理反例。网站中的短例解不能代替这项工作。</p><p>安装文件与宿主适配见<a href="https://github.com/xi-kari/xi-kari-skill/blob/main/docs/INSTALL.md" target="_blank" rel="noreferrer">项目安装指南</a>，可从<a href="https://github.com/xi-kari/xi-kari-skill/releases/latest" target="_blank" rel="noreferrer">正式发行页</a>取得技能。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="图解是否代替原文" tabindex="-1">图解是否代替原文？ <a class="header-anchor" href="#图解是否代替原文" aria-label="Permalink to &quot;图解是否代替原文？&quot;">​</a></h3><p>图解突出一项区别，不能携带全部定义与限制。每篇例解都有原文入口；需要判断正式适用条件时回到对应章节。</p><h3 id="案例里的事实和理论解释是什么关系" tabindex="-1">案例里的事实和理论解释是什么关系？ <a class="header-anchor" href="#案例里的事实和理论解释是什么关系" aria-label="Permalink to &quot;案例里的事实和理论解释是什么关系？&quot;">​</a></h3><p>真实事件的事实由案例页引用的来源承担。理论提供可对照的区别和提问方式，一个案例不会自动证明整部理论。教学情景另有标识，其中的数值不能当作现实数据。</p><h3 id="搜不到一个概念怎么办" tabindex="-1">搜不到一个概念怎么办？ <a class="header-anchor" href="#搜不到一个概念怎么办" aria-label="Permalink to &quot;搜不到一个概念怎么办？&quot;">​</a></h3><p>先尝试较短的核心词，再查看<a href="./../theory/appendix-b.html">术语索引</a>。有些普通语言表述在原文中有更精确的名称；搜索结果为空也不证明原文完全没讨论相关问题。</p><h3 id="为什么表格需要横向查看" tabindex="-1">为什么表格需要横向查看？ <a class="header-anchor" href="#为什么表格需要横向查看" aria-label="Permalink to &quot;为什么表格需要横向查看？&quot;">​</a></h3><p>一些接口卡同时比较多个字段。窄屏保留全部列，允许在表格内部横向滚动，避免为了适应屏幕而删掉条件。</p><h3 id="怎样分享准确位置" tabindex="-1">怎样分享准确位置？ <a class="header-anchor" href="#怎样分享准确位置" aria-label="Permalink to &quot;怎样分享准确位置？&quot;">​</a></h3><p>点击章节标题旁的链接，再使用“复制链接”。分享时可以同时写明书名与节号，让对方知道这条链接对应哪段原文。</p><h3 id="理论中的公式为什么有些仍是普通文字" tabindex="-1">理论中的公式为什么有些仍是普通文字？ <a class="header-anchor" href="#理论中的公式为什么有些仍是普通文字" aria-label="Permalink to &quot;理论中的公式为什么有些仍是普通文字？&quot;">​</a></h3><p>理论原文包含 Unicode 符号与文本数学记法。分章阅读保留这些记法及其内容。需要连续阅读与打印时，也可以使用已经排版的 Word 阅读版。</p>',29)])])}const b=e(o,[["render",h]]);export{u as __pageData,b as default};
